/// `error_kind` 为空而 `data` 为 `false`，意思是「发到了，没受理」。
class ReportResult {
  final bool? data;
  final String? errorKind;
  final String? errorDetail;
  final PlatformInt64? errorCode;

  const ReportResult({
    this.data,
    this.errorKind,
    this.errorDetail,
    this.errorCode,
  });

  @override
  int get hashCode =>
      data.hashCode ^
      errorKind.hashCode ^
      errorDetail.hashCode ^
      errorCode.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ReportResult &&
          runtimeType == other.runtimeType &&
          data == other.data &&
          errorKind == other.errorKind &&
          errorDetail == other.errorDetail &&
          errorCode == other.errorCode;
}

